if (!root) return
                if (root.__shopPing) clearInterval(root.__shopPing)
                if (!isAdmin) {
                    const ping = () => {
                        if (!root.isConnected) {
                            clearInterval(root.__shopPing)
                            return
                        }
                        send({ type: 'PING', blockInstanceId: payload.instanceId, buyerColor: userColor })
                    }
                    ping()
                    root.__shopPing = setInterval(ping, 30000)
                }
                const products = Array.isArray(data.products) ? data.products : []
                const payment = data.payment || {}
                const purchases = Array.isArray(data.purchases) ? data.purchases : []
                const transactions = Array.isArray(data.transactions) ? data.transactions : purchases
                const myHex = String(userColor || app.user.color || '').replace('#', '').toLowerCase()
                const isMine = item => String(item?.buyerColor || '').replace('#', '').toLowerCase() === myHex
                const list = root.querySelector('[data-shop-products]')
                // TSHIRT turns every product of this shop into a shirt with men's and women's sizes. A returning buyer finds
                // their size and shipping address already filled in (kept in their own Color, never in the shop).
                const apparel = data.apparel?.enabled === true, SIZES = ['XS', 'S', 'M', 'L', 'XL', 'XXL'], shots = def.apparelImages || {}
                const embedded = app.appState?.session === 'embed'
                root.classList.toggle('shop-embedded', embedded)
                let memory = null, renderReceipts = null
                if (apparel && !isAdmin && records) try { memory = ((await records.read('apparel')) || []).find(item => item?.id === 'apparel' && SIZES.includes(item.size)) || null } catch (_) { }
                const pencil = `<svg class='apparel-pencil' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2' aria-hidden='true'><path d='M4 20h4L19 9l-4-4L4 16v4Z'/><path d='M13.5 6.5l4 4'/></svg>`
                const sizeRow = (gender, label) => `<div class='apparel-row'><span>${label}</span><div class='apparel-sizes'>${SIZES.map(size => `<button type='button' class='apparel-size' data-gender='${gender}' data-size='${size}' aria-pressed='${memory?.gender === gender && memory?.size === size}'>${size}</button>`).join('')}</div></div>`
                const shipField = (key, label, auto) => `<input data-ship='${key}' placeholder='${label}' autocomplete='${auto}' value='${app.escapeAttr(memory?.shipping?.[key] || (key === 'country_code' ? 'US' : ''))}'>`
                const picker = () => `<div class='apparel-picker' data-apparel-picker>${memory ? `<button type='button' class='apparel-chosen' data-apparel-edit='size'>${memory.gender === 'womens' ? 'WOMENS' : 'MENS'} · ${app.escapeHtml(memory.size)}${pencil}</button>` : ''}<div class='apparel-rows' data-apparel-rows${memory ? ' hidden' : ''}>${sizeRow('mens', 'MENS')}${sizeRow('womens', 'WOMENS')}</div>${isAdmin ? '' : `${memory?.shipping ? `<button type='button' class='apparel-chosen' data-apparel-edit='ship'>SHIP TO ${app.escapeHtml(memory.shipping.name || '')}, ${app.escapeHtml(memory.shipping.city || '')}${pencil}</button>` : ''}<div class='apparel-ship' data-apparel-ship${memory?.shipping ? ' hidden' : ''}>${shipField('name', 'FULL NAME', 'name')}${shipField('address1', 'ADDRESS', 'address-line1')}<div class='apparel-ship-row'>${shipField('city', 'CITY', 'address-level2')}${shipField('state_code', 'STATE', 'address-level1')}</div><div class='apparel-ship-row'>${shipField('zip', 'ZIP', 'postal-code')}${shipField('country_code', 'COUNTRY', 'country')}</div>${shipField('email', 'EMAIL FOR UPDATES', 'email')}</div>`}</div>`
                root.classList.toggle('shop-has-products', products.length > 0)
                if (list) {
                    list.innerHTML = products.length ? products.map((item, i) => {
                        const bought = purchases.find(purchase => isMine(purchase) && (String(purchase.productIndex ?? '') === String(i) || purchase.productName === item.productName))
                        const canBuy = payment.paymentType === 'stripe-link' ? !!(item.stripePaymentLink || payment.stripePaymentLink) : payment.paymentType === 'stripe-button' ? !!((item.stripeBuyButtonId || payment.stripeBuyButtonId) && payment.stripePublishableKey) : !!payment.paymentType
                        const image = item.productImage ? `<img src='${app.escapeAttr(item.productImage)}' alt=''>` : apparel && shots.mens ? `<img data-apparel-image src='${app.escapeAttr(shots[memory?.gender === 'womens' ? 'womens' : 'mens'])}' alt=''>` : `<div class='shop-product-image-placeholder'>PRODUCT IMAGE</div>`
                        return `<div class='shop-product${apparel ? ' shop-apparel' : ''}'>${image}<div class='shop-product-body'><b>${app.escapeHtml(item.productName || 'Product')}</b><span class='shop-product-price'>${app.escapeHtml(item.productPrice || '')}</span></div>${apparel ? picker() : ''}${canBuy ? `<button class='shop-buy-btn' type='button' data-buy-product='${i}'>BUY</button>` : ``}${apparel ? `<div class='apparel-status' data-apparel-status role='status'></div>` : ''}${bought ? `<div class='shop-product-receipt'>RECEIPT ${app.escapeHtml(bought.stripe?.id || bought.id || '')}</div>` : ``}</div>`
                    }).join('') : ''
                    root.querySelectorAll('.shop-product').forEach(card => {
                        if (!card.classList.contains('shop-apparel')) return
                        const choice = { gender: memory?.gender || '', size: memory?.size || '' }
                        card.__apparelChoice = choice
                        // Typing in the shipping fields must not reach the page editor around the block.
                        card.querySelectorAll('input').forEach(input => {
                            if (window.__mobileKeyboardBind) window.__mobileKeyboardBind(input)
                            for (const type of ['touchstart', 'touchend', 'click', 'keydown', 'input']) input.addEventListener(type, event => event.stopPropagation())
                        })
                        card.querySelectorAll('.apparel-size').forEach(square => square.onclick = event => {
                            event.stopPropagation()
                            choice.gender = square.dataset.gender
                            choice.size = square.dataset.size
                            card.querySelectorAll('.apparel-size').forEach(other => other.setAttribute('aria-pressed', String(other === square)))
                            const shot = card.querySelector('[data-apparel-image]')
                            if (shot && shots[choice.gender]) shot.src = shots[choice.gender]
                            const status = card.querySelector('[data-apparel-status]')
                            if (status) status.textContent = ''
                        })
                        card.querySelectorAll('[data-apparel-edit]').forEach(button => button.onclick = event => {
                            event.stopPropagation()
                            button.hidden = true
                            const target = card.querySelector(button.dataset.apparelEdit === 'size' ? '[data-apparel-rows]' : '[data-apparel-ship]')
                            if (target) target.hidden = false
                        })
                    })
                    root.querySelectorAll('[data-buy-product]').forEach(btn => {
                        btn.onclick = event => {
                            const product = { ...(products[Number(btn.dataset.buyProduct)] || {}), productIndex: Number(btn.dataset.buyProduct) }
                            const card = btn.closest('.shop-product')
                            if (!card?.classList.contains('shop-apparel')) return app.runBlockCheckout({ def, payload, product, payment, records })
                            event?.stopPropagation?.()
                            const choice = card.__apparelChoice || {}, status = card.querySelector('[data-apparel-status]'), say = text => { if (status) status.textContent = text }
                            if (!choice.size) { say('PICK A SIZE'); card.querySelector('[data-apparel-rows]')?.removeAttribute('hidden'); return }
                            const fields = card.querySelector('[data-apparel-ship]')
                            const shipping = !fields || fields.hidden ? memory?.shipping || null : Object.fromEntries([...fields.querySelectorAll('[data-ship]')].map(input => [input.dataset.ship, input.value.trim()]))
                            if (!isAdmin && (!shipping || ['name', 'address1', 'city', 'zip', 'country_code'].some(key => !shipping[key]))) { say('ADD YOUR SHIPPING ADDRESS'); if (fields) fields.hidden = false; return }
                            const apparelChoice = { gender: choice.gender, size: choice.size, shipping }
                            const remember = () => records?.write('apparel', [{ id: 'apparel', gender: choice.gender, size: choice.size, shipping, savedAt: Date.now() }])
                            return app.runBlockCheckout({ def, payload, product, payment, records, apparel: apparelChoice, statusEl: status, buyButton: btn, embedded, remember, onReceipt: () => renderReceipts?.() })
                        }
                    })
                }
                if (isAdmin) {
                    const buyers = root.querySelector('[data-buyers]')
                    const sales = root.querySelector('[data-sales]')
                    const history = root.querySelector('[data-purchases]')
                    if (buyers) buyers.textContent = runtimeCount('buyers')
                    if (sales) sales.textContent = purchases.length
                    if (history) history.innerHTML = transactions.length ? transactions.slice(0, 10).map(item => {
                        const stripe = item.stripe || {}
                        const link = stripe.dashboardUrl ? ` <a href="${app.escapeAttr(stripe.dashboardUrl)}" target="_blank" rel="noopener">STRIPE</a>` : ''
                        const stripeMeta = [stripe.id, stripe.status, stripe.latestCharge, stripe.amount && stripe.currency ? `${stripe.amount} ${stripe.currency}` : ''].filter(Boolean).join(' / ')
                        // Shirt orders also show the size, where it ships, and what Printful said.
                        const shirt = item.apparel ? `<br>${item.apparel.gender === 'womens' ? 'WOMENS' : 'MENS'} ${app.escapeHtml(item.apparel.size || '')}${item.shipping ? ' · ' + app.escapeHtml([item.shipping.name, item.shipping.address1, item.shipping.city, item.shipping.state_code, item.shipping.zip, item.shipping.country_code].filter(Boolean).join(', ')) : ''}<br>${item.printful?.id ? 'PRINTFUL DRAFT #' + app.escapeHtml(item.printful.id) + ' · CONFIRM IT IN PRINTFUL' : item.printful?.error ? 'PRINTFUL: ' + app.escapeHtml(item.printful.error) : ''}` : ''
                        return `<div class="shop-transaction"><b>${app.escapeHtml(item.buyerColor || 'buyer')}</b> ${app.escapeHtml(item.status || 'pending')} ${app.escapeHtml(item.productName || 'Product')} ${app.escapeHtml(item.productPrice || '')}<br>${app.escapeHtml(stripeMeta || item.id || '')}${link}${shirt}</div>`
                    }).join('') : '<div>No purchases yet</div>'
                    const toggle = root.querySelector('[data-shop-admin-toggle]'), panel = root.querySelector('[data-shop-admin-panel]')
                    if (toggle && panel) toggle.onclick = () => panel.classList.toggle('open')
                    return
                }
                let receipts = root.querySelector('[data-receipts]')
                if (!receipts) {
                    receipts = document.createElement('div')
                    receipts.className = 'shop-receipts'
                    receipts.dataset.receipts = ''
                    root.querySelector('.shop-block')?.appendChild(receipts)
                }
                // Receipts are kept in the buyer's own Color (this shop's records); the seller's purchase list is never public.
                renderReceipts = async () => {
                    let saved = []
                    if (records) try { saved = ((await records.read('receipts')) || []).filter(item => item?.id) } catch (_) { }
                    const mine = [...saved, ...purchases.filter(isMine).filter(item => !saved.some(receipt => receipt.id === item.id))]
                    receipts.innerHTML = mine.length ? mine.slice(0, 5).map(item => {
                        const url = item.receiptUrl || item.stripe?.receiptUrl, receiptLink = url ? ` <a href="${app.escapeAttr(url)}" target="_blank" rel="noopener">RECEIPT</a>` : ''
                        const when = item.paidAt ? new Date(item.paidAt).toLocaleDateString() : ''
                        const printful = item.printful?.id ? 'PRINTFUL ORDER #' + item.printful.id + (item.printful.status ? ' · ' + String(item.printful.status).toUpperCase() : '') : item.printful?.error ? 'PRINT ORDER NOT PLACED YET' : ''
                        const shirt = item.apparel ? `<br>${item.apparel.gender === 'womens' ? 'WOMENS' : 'MENS'} ${app.escapeHtml(item.apparel.size || '')}${printful ? ' · ' + app.escapeHtml(printful) : ''}${item.shipTo ? '<br>SHIP TO ' + app.escapeHtml(item.shipTo) : ''}` : ''
                        return `<div class="shop-receipt"><b>${app.escapeHtml(item.productName || 'Product')}</b><br>${app.escapeHtml(item.productPrice || '')} ${app.escapeHtml(when)} ${app.escapeHtml(item.payment || item.stripe?.id || item.id || '')}${receiptLink}${shirt}${item.seller ? '<br>SELLER ID ' + app.escapeHtml(item.seller) : ''}</div>`
                    }).join('') : ''
                }
                await renderReceipts()

