actions.js:
if (data?.type === 'PAYMENT_CONFIRMED' || data?.type === 'PAYMENT_FAILED') {
                    window.ColorPayment?.handlePurchaseResult(app,data,pid)
                    return
                }
                if (data?.type === 'STRIPE_PREPARED' || data?.type === 'STRIPE_AGENT_ERROR') {
                    const pending = app.pendingStripeRequests.get(data.requestId)
                    if (!pending || pending.targetPeer !== pid) return
                    clearTimeout(pending.timer)
                    app.pendingStripeRequests.delete(data.requestId)
                    data.type === 'STRIPE_PREPARED' ? pending.resolve(data) : pending.reject(new Error(data.error || 'Seller Stripe agent failed.'))
                    return
